/**
 * Formats a duration given in milliseconds as "<h>h <mm>m <ss>s".
 *
 * @param ms - Duration in milliseconds. Must be a non-negative, finite integer.
 * @returns The formatted duration string; `h` is unpadded, `mm` and `ss` are zero-padded to 2 digits. Sub-second milliseconds are truncated.
 * @throws {RangeError} formatDurationMs: ms must be a finite number
 * @throws {RangeError} formatDurationMs: ms must be an integer
 * @throws {RangeError} formatDurationMs: ms must be non-negative
 */
export function formatDurationMs(ms: number): string {
  if (typeof ms !== "number" || !Number.isFinite(ms)) {
    throw new RangeError("formatDurationMs: ms must be a finite number");
  }
  if (!Number.isInteger(ms)) {
    throw new RangeError("formatDurationMs: ms must be an integer");
  }
  if (ms < 0) {
    throw new RangeError("formatDurationMs: ms must be non-negative");
  }

  const totalSeconds = Math.floor(ms / 1000);
  const hours = Math.floor(totalSeconds / 3600);
  const minutes = Math.floor((totalSeconds % 3600) / 60);
  const seconds = totalSeconds % 60;

  const mm = String(minutes).padStart(2, "0");
  const ss = String(seconds).padStart(2, "0");

  return `${hours}h ${mm}m ${ss}s`;
}
